  "replacement_segments": [
    {
      "id": "s2",
      "text": "Lina stood firm, her eyes meeting the fox's weary gaze. She knew the humming was a mystery that needed solving, and she wouldn't turn back now. Mosk let out a soft huff, his whiskers twitching as he considered her determination."
    },
    {
      "id": "s3",
      "text": "Mosk pointed at the door, but Lina reached into her pocket and pulled out the last apple of the season. She set it on the step between them and said, this is for the trouble of walking me down. Mosk stared at the apple for a long time. Then he stood up, tied his vest, and stepped onto the first stair without a word."
    }
  ],
  "active_scene_id": "s2"
